sys_script_fix.script:
/**
 * Description: Clears the 'assignment_group' field for all records 
 * in Iniciativa, Plan Municipal, and Plan Organismo tables.
 */
(function() {
    var tables = [
        'x_431220_ciclo_iniciativa',
        'x_431220_ciclo_plan_municipal',
        'x_431220_ciclo_plan_organismo' // Source table
    ];

    tables.forEach(function(tableName) {
        var gr = new GlideRecord(tableName);

        // 1. Target only records that actually have a group assigned
        gr.addNotNullQuery('assignment_group');
        gr.query();

        var recordCount = gr.getRowCount();

        if (recordCount > 0) {
            // 2. Disable Workflows and Business Rules for performance
            gr.setWorkflow(false);

            // 3. Prevent the 'Updated' date and 'Updated by' from changing
            gr.autoSysFields(false);

            // 4. Nullify the field and perform bulk update
            gr.setValue('assignment_group', '');
            gr.updateMultiple();

            gs.info('>>> [CLEANUP] Table ' + tableName + ': Cleared ' + recordCount + ' records.');
        } else {
            gs.info('>>> [CLEANUP] Table ' + tableName + ': No records found with assignment groups.');
        }
    });
})();
